import { sql, type SQL } from 'drizzle-orm';
import { bigint, date, numeric, timestamp, varchar } from 'drizzle-orm/pg-core';
import { STATUS_AKTIF } from '@sit/shared';

/*
 * Pembangun kolom yang dipakai berulang. Semua nama constraint di skema ditulis eksplisit
 * dan sama persis dengan nama yang dibuat PostgreSQL dari DDL v3.1 (mis. `satuan_kode_key`,
 * `barang_id_kategori_fkey`), agar migrasi yang dihasilkan drizzle-kit nanti tidak salah sasaran.
 */

/** Kunci utama `bigint generated by default as identity`. */
export const kolomId = () =>
  bigint('id', { mode: 'number' }).primaryKey().generatedByDefaultAsIdentity();

/** Kolom rujukan ke `id` tabel lain. FK dideklarasikan di konfigurasi tabel (nama eksplisit). */
export const kolomRef = (nama: string) => bigint(nama, { mode: 'number' });

/** Uang: bigint rupiah utuh (CLAUDE.md aturan 7). */
export const uang = (nama: string) => bigint(nama, { mode: 'number' });

/** Kuantitas numeric(14,3). Bertipe string di TS; aritmatika hanya lewat helper qty (aturan 8). */
export const qty = (nama: string) => numeric(nama, { precision: 14, scale: 3 });

/** Waktu `timestamptz` (UTC di DB, tampil Asia/Jakarta). */
export const timestamptz = (nama: string) => timestamp(nama, { withTimezone: true, mode: 'date' });

/** Tanggal (mis. tanggal operasional lokal Asia/Jakarta) sebagai string `YYYY-MM-DD`. */
export const tanggal = (nama: string) => date(nama, { mode: 'string' });

export const statusAktif = () =>
  varchar('status_aktif', { length: 10, enum: STATUS_AKTIF }).notNull().default('AKTIF');

export const dibuatPada = () => timestamptz('dibuat_pada').notNull().defaultNow();

export const diubahPada = () => timestamptz('diubah_pada');

const POLA_KOLOM = /^[a-z_]+$/;
const POLA_NILAI = /^[A-Z_]+$/;

/**
 * Menyusun `kolom in ('A','B',...)` untuk CHECK constraint dari daftar enum di packages/shared,
 * sehingga nilai enum hanya didefinisikan di satu tempat. Nilainya konstanta kode (bukan input
 * pengguna) dan divalidasi polanya, jadi aman ditulis sebagai literal SQL.
 */
export function dalamDaftar(kolom: string, nilai: readonly string[]): SQL {
  if (!POLA_KOLOM.test(kolom)) throw new Error(`Nama kolom tidak valid: ${kolom}`);
  for (const v of nilai) {
    if (!POLA_NILAI.test(v)) throw new Error(`Nilai enum tidak valid: ${v}`);
  }
  return sql.raw(`${kolom} in (${nilai.map((v) => `'${v}'`).join(',')})`);
}
